begin;
alter table public.telegram_budget_notification_events drop constraint telegram_budget_notification_events_threshold_check;
alter table public.telegram_budget_notification_events add constraint telegram_budget_notification_events_threshold_check check (threshold in ('budget_near_limit','budget_over_limit','daily_summary','weekly_summary','test_notification'));
create or replace function public.claim_telegram_budget_notification_worker() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare e public.telegram_budget_notification_events%rowtype; chat text; begin update public.telegram_budget_notification_events x set status='failed',failed_at=now(),last_error_class='destination_unavailable' where x.status in ('pending','sending') and (not exists(select 1 from public.user_integrations i where i.id=x.integration_id and i.provider='telegram' and i.status='active' and i.deleted_at is null) or (x.threshold<>'test_notification' and not exists(select 1 from public.notification_preferences p where p.user_id=x.user_id and p.channel='telegram' and p.preference_key=x.threshold and p.enabled))); select x.* into e from public.telegram_budget_notification_events x join public.user_integrations i on i.id=x.integration_id and i.provider='telegram' and i.status='active' and i.deleted_at is null left join public.notification_preferences p on p.user_id=x.user_id and p.channel='telegram' and p.preference_key=x.threshold where ((x.status='pending' and x.next_retry_at<=now()) or (x.status='sending' and x.last_attempt_at<now()-interval '10 minutes')) and (x.threshold='test_notification' or p.enabled) order by x.created_at for update of x skip locked limit 1; if not found then return null; end if; select external_chat_id into chat from public.user_integrations where id=e.integration_id; update public.telegram_budget_notification_events set status='sending',attempts=attempts+1,last_attempt_at=now(),last_error_class=null where id=e.id; return e.payload||jsonb_build_object('notification_id',e.id::text,'threshold',e.threshold,'chat_id',chat,'attempt',e.attempts+1); end; $$;
create or replace function public.get_telegram_diagnostics() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare u uuid:=auth.uid(); i public.user_integrations%rowtype; worker_at timestamptz; begin if u is null then raise exception 'Authentication required'; end if; select * into i from public.user_integrations where user_id=u and provider='telegram' and status='active' and deleted_at is null; if not found then return jsonb_build_object('connection','disconnected','worker','disconnected','pending',0,'retryable',0,'failed',0); end if; select max(end_time) into worker_at from cron.job_run_details where jobid=(select jobid from cron.job where jobname='telegram-notification-worker'); return jsonb_build_object('connection','connected','worker',case when worker_at is not null and worker_at>now()-interval '5 minutes' then 'healthy' else 'needs_attention' end,'last_worker_at',worker_at,'last_delivered_at',(select max(delivered_at) from public.telegram_budget_notification_events where user_id=u and status='delivered'),'last_failed_at',(select max(failed_at) from public.telegram_budget_notification_events where user_id=u and status='failed'),'failure_class',(select last_error_class from public.telegram_budget_notification_events where user_id=u and status='failed' order by failed_at desc limit 1),'pending',(select count(*) from public.telegram_budget_notification_events where user_id=u and status='pending' and attempts=0),'retryable',(select count(*) from public.telegram_budget_notification_events where user_id=u and status='pending' and attempts>0),'failed',(select count(*) from public.telegram_budget_notification_events where user_id=u and status='failed')); end; $$;
create or replace function public.queue_telegram_test_notification() returns text language plpgsql security definer set search_path=public,pg_temp as $$ declare u uuid:=auth.uid(); i public.user_integrations%rowtype; begin if u is null then raise exception 'Authentication required'; end if; select * into i from public.user_integrations where user_id=u and provider='telegram' and status='active' and deleted_at is null; if not found then raise exception 'Telegram not connected'; end if; perform pg_advisory_xact_lock(hashtext('telegram-test:'||u::text)); if exists(select 1 from public.telegram_budget_notification_events where user_id=u and threshold='test_notification' and created_at>now()-interval '5 minutes') then return 'already_queued'; end if; insert into public.telegram_budget_notification_events(user_id,integration_id,budget_id,period_start,threshold,payload,next_retry_at) values(u,i.id,null,current_date,'test_notification',jsonb_build_object('test_message',true,'currency','USD'),now()); return 'queued'; end; $$;
revoke all on function public.get_telegram_diagnostics() from public; grant execute on function public.get_telegram_diagnostics() to authenticated; revoke all on function public.queue_telegram_test_notification() from public; grant execute on function public.queue_telegram_test_notification() to authenticated; revoke all on function public.claim_telegram_budget_notification_worker() from public,anon,authenticated; grant execute on function public.claim_telegram_budget_notification_worker() to service_role; commit;